tool_and_message_events.command:
/bin/bash -lc 'set -eu
review_root=$(pwd)
review_copy=$(mktemp -d "$review_root/.desk-review.XXXXXX")
trap '"'python3 -c \"import shutil, sys; shutil.rmtree(sys.argv[1])\" \""'$review_copy"'"' EXIT
cp -R -- \""'$review_root/release/." "$review_copy/"
cd "$review_copy"
npm --cache "$review_copy/.npm-cache" install --offline --ignore-scripts --no-audit --no-fund "$review_root/vendor/hono-4.13.19.tgz"
node -p '"'\"Hono \" + require(\"./node_modules/hono/package.json\").version + \", Node \" + process.version'
npm --cache \""'$review_copy/.npm-cache" test
node --input-type=module <<'"'EOF'
import assert from 'node:assert/strict';
import app from './app.mjs';

const scenarios = [
  {name: 'valid record', id: 'f2', session: 'day', status: 200, steps: 'dispatch,session,read'},
  {name: 'missing session', id: 'f2', status: 401, error: 'sign_in', steps: 'dispatch,session'},
  {name: 'missing record', id: 'missing', session: 'day', status: 404, error: 'not_found', steps: 'dispatch,session,read'},
  {name: 'invalid record', id: 'r9', session: 'day', status: 502, error: 'invalid_record', steps: 'dispatch,session,read,error'},
];

for (const scenario of scenarios) {
  const headers = scenario.session ? {'x-shift': scenario.session} : {};
  const response = await app.request('/desk/' + scenario.id, {method: 'GET', headers});
  const contentType = response.headers.get('content-type');
  const steps = response.headers.get('x-desk-steps');
  const body = await response.json();
  const failures = [];
  const check = (name, verify) => {
    try { verify(); } catch { failures.push(name); }
  };

  check('status', () => assert.equal(response.status, scenario.status));
  check('steps', () => assert.equal(steps, scenario.steps));
  check('media type', () => assert.match(contentType, /"'^application'"\\/json(?:;|"'$)/i));
  if (scenario.error) {
    check('"'error', () => assert.equal(body.error, scenario.error));
  } else {
    check('card keys', () => assert.deepEqual(Object.keys(body).sort(), ['id', 'title']));
    check('id', () => assert.equal(body.id, scenario.id));
    check('title', () => assert.ok(typeof body.title === 'string' && body.title.length > 0));
  }

  console.log(JSON.stringify({scenario: scenario.name, status: response.status, contentType, body, steps, failures}));
  if (failures.length) process.exitCode = 1;
}
EOF"

